 await prepareShell();
 await prepareOfflineCatalog({version:2,...scope,role:current.role,branch,currency:c,name:current.name,capturedAt:ledger?.capturedAt||new Date().toISOString(),products,receivableActions,...(references?{references}:{}),...(ledger?{ledger}: {}),...(localPrices?{localPrices}:{}),...(mixedRates?{mixedRates}:{})},pass);
