function queueIdentity(){if(!current||!staffIdentity)throw Error('Authenticated workspace required');return {store:current.id,actor:staffIdentity.id}}
async function queueOperation(operation,attempted=false){if(!canQueue(operation))throw Error('Operation requires live server');const pass=prompt('عبارة تشفير قائمة العمليات (12 حرفاً على الأقل). لا تستخدم كلمة مرور الحساب.');if(pass===null)throw Error('Queue cancelled');const n=await addQueuedOperation({...queueIdentity(),pass,operation,attempted});message('محفوظ محلياً، بانتظار اعتماد الخادم: '+n+' عملية.');return n}
