function queueFailure(x){const en=document.documentElement.lang==='en';return x.failure==='authorization'?(en?'Sign in again / check permissions':'أعد تسجيل الدخول وراجع الصلاحيات'):x.failure==='conflict'?(en?'Conflict — review server records':'تعارض — راجع سجلات الخادم'):x.attemptedAt?(en?'Not confirmed — retry same reference':'غير مؤكد — أعد نفس المرجع'):(en?'Not sent':'لم تُرسل')}
