async function resolveReceivableDecision(x){
 const status=await api.resolveReceivable(current.id,x,'inspect'),ref=' — '+x.requestId;
 if(status==='confirmed')return confirm(tr('تأكد تسجيل العملية على الخادم. إزالة المسودة فقط؟')+ref)?status:null;
 if(status==='cancelled'||status==='conflict_acknowledged')return confirm(tr('سبق إغلاق مرجع العملية. إزالة النسخة المحلية؟')+ref)?status:null;
 if(status==='not_recorded'){
  if(!confirm(tr('العملية غير مسجلة. إلغاء مرجعها نهائياً بعد مراجعة النقد الفعلي؟')+ref))return null;
  return api.resolveReceivable(current.id,x,'cancel');
 }
 if(status==='conflict'){
  if(!confirm(tr('المرجع مرتبط ببيانات مختلفة. راجع السجلات قبل إغلاق المسودة المتعارضة دون تعديل أي قيد مالي.')+ref))return null;
  return api.resolveReceivable(current.id,x,'acknowledge');
 }
 throw Error('Unknown status');
}
