async function showProductOriginals(){const r=await api.productOriginals(current.id,catalogDraft.id),root=el('originalRows');root.replaceChildren();for(const x of r){const d=node('div','');d.append(node('span',x.alt+' — '+(x.uploaded?(x.published?'منشورة':'خاصة'):'بانتظار رفع الملف')));if(x.uploaded){const b=node('button',x.published?'إلغاء النشر':'نشر الصورة');b.type='button';b.onclick=()=>run(async()=>{if(!x.published&&!confirm('نشر هذه الصورة لزوار المتجر؟'))return;await api.publishProductOriginal(current.id,x.id,!x.published);await showProductOriginals()});d.append(b)}else{const b=node('button','استكمال رفع هذا الملف');b.type='button';b.onclick=()=>run(async()=>{const file=el('originalFile').files[0];if(!file)throw Error('Choose image');await api.uploadProductOriginal(current.id,x,await encodeOriginal(file));el('originalFile').value='';await showProductOriginals()});d.append(b)}root.append(d)}}
async function encodeOriginal(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10000000)throw Error('Invalid image');const bm=await createImageBitmap(file);try{if(bm.width>8000||bm.height>8000)throw Error('Image dimensions');const cv=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bm.width,bm.height));cv.width=Math.max(1,Math.round(bm.width*scale));cv.height=Math.max(1,Math.round(bm.height*scale));const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);c.drawImage(bm,0,0,cv.width,cv.height);for(const q of [.9,.8,.65]){const blob=await new Promise(r=>cv.toBlob(r,'image/jpeg',q));if(blob&&blob.size<=2000000)return blob}throw Error('Image too large')}finally{bm.close()}}
