async function encodePhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5000000)throw Error('Invalid image');const bm=await createImageBitmap(file);try{if(bm.width>6000||bm.height>6000)throw Error('Image too large');for(const edge of [480,360,240,160]){const cv=document.createElement('canvas'),scale=Math.min(1,edge/Math.max(bm.width,bm.height));cv.width=Math.max(1,Math.round(bm.width*scale));cv.height=Math.max(1,Math.round(bm.height*scale));const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);c.drawImage(bm,0,0,cv.width,cv.height);const data=cv.toDataURL('image/jpeg',.72).split(',')[1];if(data?.length<=32000&&data.startsWith('/9j/'))return data}throw Error('Image compression failed')}finally{bm.close()}}
