let warrantyQuery=null,warrantyOffset=0,warrantyMore=false;
function resetWarrantyRegister(){warrantyQuery=null;warrantyOffset=0;warrantyMore=false;el('saleWarrantySearch').reset();el('saleWarrantyRows').replaceChildren();el('saleWarrantyStatus').textContent='';el('saleWarrantyPrev').disabled=el('saleWarrantyNext').disabled=true}
async function loadWarrantyRegister(offset=0){if(!warrantyQuery||!current||!['owner','cashier'].includes(current.role)||staffDenied.has('sales_read')||staffDenied.has('warranty_read'))return;const store=current.id,q=warrantyQuery,data=await api.saleWarranties(store,q.query,q.state,offset);if(current?.id!==store||warrantyQuery!==q)return;warrantyOffset=offset;warrantyMore=data.length===50;el('saleWarrantyRows').replaceChildren(...data.map(x=>{const r=row([x.number,x.product_name+' — '+x.sku,x.customer||'—',x.serial||'—',x.months,x.until_date,x.covered_units,tr(({active:'ساري زمنياً',expired:'منتهي',returned:'ملغاة بسبب الإرجاع'})[x.state])]);const td=node('td','');if(!staffDenied.has('receipt_read'))td.append(button('عرض الإيصال',()=>showReceipt({...x,id:x.sale_id})));r.append(td);return r}));el('saleWarrantyStatus').textContent=data.length?'':tr('لا توجد سجلات مطابقة');el('saleWarrantyPrev').disabled=offset===0;el('saleWarrantyNext').disabled=!warrantyMore}
el('saleWarrantySearch').onsubmit=e=>{e.preventDefault();const q=Object.fromEntries(new FormData(e.target));run(async()=>{warrantyQuery={query:q.query.trim(),state:q.state};warrantyOffset=0;await loadWarrantyRegister()})};
el('saleWarrantyPrev').onclick=()=>run(()=>loadWarrantyRegister(Math.max(0,warrantyOffset-50)));
el('saleWarrantyNext').onclick=()=>run(()=>warrantyMore&&loadWarrantyRegister(warrantyOffset+50));
