el('posLoyaltyCode').addEventListener('input',()=>{if(el('posLoyaltyCode').value.trim())clearLocalPricing();el('posLoyaltyStatus').textContent='';controls()});
el('sell').addEventListener('click',()=>run(async()=>{if(hasOffline()&&!offlineRestored)return;if(!attempt){if(branchPending)return;const draft=makeInvoiceAttempt(),token=el('posLoyaltyCode').value.trim(),localPricing=await localMembershipConfirmation(draft);if(localPricing){if(!confirm(tr('هل تم قبض المبلغ الصافي وموافقة الزبون؟')+' — '+money(localPricing.expected,draft.currency)))return;attempt=Object.freeze({...draft,localPricing})}else if(token){if(!navigator.onLine)throw Error('POS authorization requires connection');const q=await api.posQuote(draft,token);const lineSummary=draft.lines.map(l=>(cart.get(l.product_id)?.name||l.product_id)+' × '+l.units+' — '+money(q.prices[l.product_id],q.currency)).join('\n');const summary=(q.price_tier?membershipLabel(q.price_tier)+' — ':'')+tr('قبل الخصم')+': '+money(q.gross_minor,q.currency)+' — '+tr('الخصم')+': '+money(q.discount_minor,q.currency)+' — '+tr('النقد المقبوض')+': '+money(q.total_minor,q.currency)+' — '+tr('النقاط المستبدلة')+': '+(q.spend_requested!==null?q.spend_points_used:q.points)+(q.spend_requested!==null?' — '+tr('خصم النقاط')+': '+money(q.points_discount_minor,q.currency):'')+'\n'+lineSummary;el('posLoyaltyStatus').textContent=summary;if(!confirm(summary+'\n'+tr('هل تم قبض المبلغ الصافي وموافقة الزبون؟')))return;attempt=Object.freeze({...draft,loyalty:Object.freeze({token,expected:q.total_minor,...(q.price_tier||q.spend_requested!==null?{prices:Object.freeze({...q.prices})}:{}),...(q.spend_requested!==null?{spend:Object.freeze({requested:q.spend_requested,used:q.spend_points_used,points_discount_minor:q.points_discount_minor,currency_per_usd_minor:q.currency_per_usd_minor,points_per_usd:q.points_per_usd,max_redeem_bps:q.max_redeem_bps,base_total_minor:q.base_total_minor})}:{})})})}else{if(!confirm('تسجيل بيع نقدي تجريبي فقط؟'))return;attempt=draft}el('pending').textContent='معرف العملية: '+attempt.requestId;renderCart()}const r=await api.recordSale(attempt);if(offlineRestored&&offlineScope())localStorage.removeItem(offlineScope());offlineRestored=false;attempt=null;cart.clear();resetSaleInvoice();el('pending').textContent='تم تأكيد العملية '+r.request_id;await load();message('تم تسجيل البيع رقم '+r.number+' — '+money(r.total_minor,r.currency))}));
el('logout').addEventListener('click',()=>run(async()=>{if((stockCount.pending()||attempt||stockAttempt||cashAttempt||receivableAttempt||returnAttempt||costAttempt||operations.pending())&&!confirm('هناك عملية غير مؤكدة. احفظ معرفها وتحقق من السجل قبل تكرارها. خروج؟'))return;try{await api.signOut()}finally{clear()}},true));
