const operations=createOperationsPanel({api,run,showRepairReceipt,refresh:load,queueOperation,queuedOps,blocked:()=>!!(hasOffline()||attempt||stockAttempt||cashAttempt||receivableAttempt||returnAttempt||costAttempt),resolveLocalPricing:resolveReceivableDecision,getMembershipCart:async()=>{const sale=makeInvoiceAttempt(),localPricing=await localMembershipConfirmation(sale),membership=await financedMembership(sale);return {...sale,...(localPricing?{localPricing}:{}),...(membership?{membership}:{})}},getCart:()=>{if(el('posLoyaltyCode').value.trim()||el('localPriceCustomer').value)throw Error('Membership pricing not available for trade-in');return {branch:el('saleBranch').value||null,currency:selectedCurrency,lines:[...cart.values()].map(({product_id,units,expected_price_minor})=>({product_id,units,expected_price_minor})),invoice:captureSaleInvoice([...cart.values()])}},clearCart:()=>{cart.clear();resetSaleInvoice()},message});
